import { db } from './client';

export async function listOrders(opts: { from?: Date; to?: Date; limit?: number }) {
  return db.order.findMany({
    where: { createdAt: { gte: opts.from, lt: opts.to } },
    include: { customer: true },
    orderBy: { createdAt: 'desc' },
    take: opts.limit,
  });
}

