import { listOrders } from '@/lib/db/orders';
import { requirePermission } from '@/lib/auth';
import { formatMoney } from '@/lib/money';

export const dynamic = 'force-dynamic';

export default async function AdminOrdersPage() {
  await requirePermission('orders:read');

  // TODO: pagination controls

  const orders = await listOrders({ limit: 50 });

  return (
    <main className="p-6">
      <h1 className="mb-4 text-xl font-semibold">Orders</h1>
      <div role="toolbar" className="mb-2 flex gap-2">
        <input type="date" name="from" aria-label="From" />
        <input type="date" name="to" aria-label="To" />
      </div>
      <table className="w-full text-sm">
        <thead>
          <tr><th>Order</th><th>Date</th><th>Customer</th><th>Total</th><th>Status</th></tr>
        </thead>
        <tbody>
          {orders.map(o => (
            <tr key={o.id}>
              <td>{o.id}</td>
              <td>{o.createdAt.toISOString().slice(0, 10)}</td>
              <td>{o.customer.name}</td>
              <td>{formatMoney(o.total)}</td>
              <td>{o.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

